    const canceled = await mk(a, { title: "canc", dueAt: "2026-01-01T00:00:00.000Z" });
    await issueRepo.setIssueStatus(a.org.id, canceled.id, "canceled");
    const dl = await mk(d, { title: "deleted org", dueAt: "2026-01-01T00:00:00.000Z" });
    await orgRepo.archiveOrg(d.org.id);

    const seen: string[] = [];
    const off = subscribe("issue.overdue", (p) => { seen.push(p.issueId); });

    await runOverdueIssueJob(NOW);
    expect(seen).toEqual([late.id]);
    await runOverdueIssueJob(at(1));
    expect(seen.sort()).toEqual([late.id, exact.id].sort());
    seen.length = 0;
    await runOverdueIssueJob(at(2));
    expect(seen).toEqual([]);
    await issueRepo.setIssueStatus(a.org.id, late.id, "canceled");
    await runOverdueIssueJob(at(3));
    expect(seen).toEqual([]);
    await issueRepo.setIssueStatus(a.org.id, late.id, "todo");
    await runOverdueIssueJob(at(4));
    expect(seen).toEqual([late.id]);
    // cancel+reopen between sweeps: not re-announced
    seen.length = 0;
    await issueRepo.setIssueStatus(a.org.id, late.id, "canceled");
    await issueRepo.setIssueStatus(a.org.id, late.id, "todo");
    await runOverdueIssueJob(at(5));
    expect(seen).toEqual([]);
    // due date moved out, then passes
    await issueRepo.updateIssue({ orgId: a.org.id, issueId: exact.id, dueAt: at(7).toISOString() } as any);
    await runOverdueIssueJob(at(6));
    expect(seen).toEqual([]);
    await runOverdueIssueJob(at(8));
    expect(seen).toEqual([exact.id]);
    expect(seen).not.toContain(dl.id);
    off();

    const notes = await notificationRepo.listNotifications({ orgId: a.org.id, recipientId: a.userIds.member, limit: 50 } as any);
    expect(notes.items.map((n) => n.kind)).toEqual(["issue_overdue", "issue_overdue"]);

    // stats
    const stats = await projectRepo.getProjectStats(a.org.id, a.project.id);
    expect(stats).toMatchObject({ openIssues: 2, closedIssues: 1, overdueIssues: 2 });
  });

  it("preferences", async () => {
    resetOverdueTracking();
    const b = await createTenant("sb");
    await prefRepo.upsertPreference({ orgId: b.org.id, userId: b.userIds.member, kind: "issue_due_soon", inApp: false, email: false, digestOnly: false } as any);
    await prefRepo.upsertPreference({ orgId: b.org.id, userId: b.userIds.admin, kind: "issue_overdue", inApp: false, email: false, digestOnly: false } as any);
    await mk(b, { title: "m", dueAt: "2026-01-01T00:00:00.000Z", assigneeId: b.userIds.member });
    await mk(b, { title: "a", dueAt: "2026-01-01T00:00:00.000Z", assigneeId: b.userIds.admin });
    await runOverdueIssueJob(NOW);
    const m = await notificationRepo.listNotifications({ orgId: b.org.id, recipientId: b.userIds.member, limit: 50 } as any);
    const ad = await notificationRepo.listNotifications({ orgId: b.org.id, recipientId: b.userIds.admin, limit: 50 } as any);
    expect(m.items.length).toBe(1);
    expect(ad.items.length).toBe(0);
  });

  it("lifecycle dates", async () => {
    const c = await createTenant("sc");
    const i = await mk(c, { title: "x" });
    const s1 = await issueRepo.setIssueStatus(c.org.id, i.id, "in_progress");
    const d1 = await issueRepo.setIssueStatus(c.org.id, i.id, "done");
    expect(d1.completedAt).not.toBeNull();
    const r = await issueRepo.setIssueStatus(c.org.id, i.id, "in_progress");
    expect(r.completedAt).toBeNull();
    expect(r.startedAt).toBe(s1.startedAt);
    await new Promise((res) => setTimeout(res, 5));
    const d2 = await issueRepo.setIssueStatus(c.org.id, i.id, "canceled");
    expect(d2.completedAt).not.toBeNull();
    expect(d2.completedAt! > d1.completedAt!).toBe(true);
    expect(d2.startedAt).toBe(s1.startedAt);
  });
});
